*{box-sizing:border-box} :root{--ink:#071018;--paper:#edf3f3;--muted:#75848b;--cyan:#61e9e9;--blue:#43d5e0;--red:#ff646b;--line:rgba(207,239,239,.16);--mono:'DM Mono',monospace;--display:'Barlow Condensed',Impact,sans-serif}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#050b10;color:var(--paper);font-family:var(--display);user-select:none;-webkit-user-select:none}body{display:grid;place-items:center}#game-shell{position:relative;width:min(100vw,177.78vh);height:min(100vh,56.25vw);min-height:320px;overflow:hidden;background:#09121a;isolation:isolate}#view{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette,.scanlines{position:absolute;inset:0;pointer-events:none;z-index:2}.vignette{background:radial-gradient(ellipse at 50% 48%,transparent 34%,rgba(2,7,12,.18) 68%,rgba(2,7,12,.72) 130%)}.scanlines{opacity:.13;background:repeating-linear-gradient(0deg,transparent 0px,transparent 3px,rgba(0,0,0,.24) 4px);mix-blend-mode:multiply}.hud{z-index:4}.hidden{display:none!important}.screen{position:absolute;inset:0;z-index:8;background:linear-gradient(90deg,rgba(4,11,17,.97) 0%,rgba(5,13,20,.91) 38%,rgba(5,13,20,.42) 75%,rgba(4,11,17,.35)),linear-gradient(0deg,rgba(4,11,17,.75),transparent 30%);overflow:hidden}.menu-top,.menu-footer{position:absolute;left:5.2%;right:5.2%;display:flex;align-items:center;justify-content:space-between;z-index:3}.menu-top{top:6.5%}.brand{display:flex;align-items:center;gap:12px;font-size:19px;font-weight:800;letter-spacing:2px}.brand-mark{height:31px;width:31px;display:grid;place-items:center;background:var(--cyan);color:#071018;font-size:23px;font-weight:900;clip-path:polygon(0 0,100% 0,100% 75%,75% 100%,0 100%)}.brand-light{font-weight:500;color:#9eb0b6}.season,.menu-footer{font:10px var(--mono);letter-spacing:1.2px;color:#8e9ba0}.season span{color:var(--cyan);padding:0 6px}.menu-content{position:absolute;z-index:3;left:10.4%;top:20%;width:min(38%,510px)}.eyebrow{display:flex;align-items:center;gap:10px;color:#83d9dc;font:10px var(--mono);letter-spacing:1.2px}.eyebrow>span{display:inline-block;width:19px;height:2px;background:var(--cyan);box-shadow:0 0 10px var(--cyan)}h1,h2{font-weight:900;letter-spacing:-.7px;line-height:.83;margin:22px 0 14px;font-size:clamp(57px,7vw,100px)}h1 em,h2 em{font-style:normal;color:var(--cyan)}.lead{margin:18px 0 27px;color:#acb8bc;font-size:17px;line-height:1.35;letter-spacing:.3px}.match-card{width:min(100%,390px);border:1px solid rgba(173,222,228,.18);background:rgba(12,26,34,.72);padding:13px 15px 11px;backdrop-filter:blur(8px)}.card-head{display:flex;justify-content:space-between;padding-bottom:10px;border-bottom:1px solid var(--line);font:10px var(--mono);letter-spacing:1px;color:#becbcd}.card-head b{font-weight:400;color:#697c84}.brief-row{display:flex;align-items:center;padding:12px 0 10px;gap:9px}.brief-icon{color:var(--cyan);font-size:21px;width:28px;text-align:center}.brief-icon.target{margin-left:12px}.brief-row div:nth-child(2),.brief-row div:nth-child(4){display:flex;flex-direction:column;gap:3px;min-width:76px}.brief-row small{color:#7d9097;font:9px var(--mono);letter-spacing:.7px}.brief-row strong{font-size:16px;letter-spacing:.5px}.brief-foot{border-top:1px solid var(--line);padding-top:10px;display:flex;align-items:center;gap:7px;font:9px var(--mono);letter-spacing:.5px;color:#bcc8cb}.brief-foot i{font-style:normal;margin:0 6px;color:#56676e}.blue-dot,.red-dot{width:7px;height:7px;border-radius:50%;background:var(--blue);box-shadow:0 0 8px var(--blue)}.red-dot{background:var(--red);box-shadow:0 0 8px var(--red)}.deploy-button{display:flex;justify-content:space-between;align-items:center;width:min(100%,390px);height:52px;margin-top:16px;padding:0 18px;border:0;background:var(--cyan);color:#061319;cursor:pointer;font:800 16px var(--display);letter-spacing:1px;transition:background .18s,transform .18s,box-shadow .18s;clip-path:polygon(0 0,97% 0,100% 26%,100% 100%,0 100%)}.deploy-button:hover{background:#a1ffff;box-shadow:0 0 30px rgba(97,233,233,.3);transform:translateY(-2px)}.deploy-button b{font-size:25px;font-weight:500}.menu-note{margin-top:11px;color:#62757d;font:9px var(--mono);letter-spacing:.8px}.menu-note span{color:var(--cyan);font-size:14px;vertical-align:-1px;margin-right:5px}.menu-footer{bottom:4%;font-size:9px}.menu-footer i{font-style:normal;color:#66e8a4;margin-left:7px}.hero-art{position:absolute;right:5%;top:11%;width:48%;height:85%;overflow:hidden;opacity:.95}.hero-ring{position:absolute;border:1px solid rgba(97,233,233,.23);border-radius:50%;width:72%;aspect-ratio:1;right:4%;top:9%;transform:rotate(-30deg) skewY(-6deg);box-shadow:inset 0 0 75px rgba(57,194,204,.05),0 0 90px rgba(57,194,204,.06)}.ring-two{width:55%;right:12%;top:18%;border-color:rgba(97,233,233,.15);border-style:dashed}.hero-cross{position:absolute;top:17%;right:39%;color:rgba(97,233,233,.55);font:22px var(--mono}.hero-soldier{position:absolute;width:43%;height:77%;bottom:-2%;right:22%;filter:drop-shadow(0 0 32px rgba(61,205,216,.2));}.soldier-head{position:absolute;left:36%;top:12%;width:31%;height:21%;border-radius:40% 40% 33% 33%;background:linear-gradient(115deg,#273e48,#0a151d 60%,#172b35);border:1px solid rgba(131,233,236,.26);clip-path:polygon(22% 0,80% 0,100% 65%,67% 100%,21% 85%,0 42%)}.soldier-head:after{content:'';position:absolute;left:0;right:-18%;top:40%;height:17%;background:linear-gradient(90deg,#153b47,#51e2e5 70%,#254b54);box-shadow:0 0 14px #4bd7dc}.soldier-body{position:absolute;left:12%;top:31%;width:73%;height:72%;background:linear-gradient(105deg,#14252d,#0b161d 44%,#20323a);clip-path:polygon(27% 0,72% 0,94% 18%,100% 65%,84% 100%,17% 100%,0 69%,7% 21%);border-top:1px solid rgba(119,211,216,.25)}.soldier-body:before{content:'';position:absolute;inset:12% 21% 28%;background:repeating-linear-gradient(0deg,transparent 0 22px,rgba(121,179,187,.12) 23px 24px),linear-gradient(90deg,transparent 47%,rgba(86,204,212,.18) 50%,transparent 54%)}.soldier-rifle{position:absolute;z-index:2;right:-6%;top:43%;width:94%;height:6%;background:linear-gradient(0deg,#070e13,#334951 48%,#0a1116);transform:rotate(-13deg);box-shadow:0 2px 0 #020608}.soldier-rifle:after{content:'';position:absolute;right:8%;top:-200%;width:23%;height:500%;background:#172a31;clip-path:polygon(0 0,88% 0,100% 100%,20% 75%)}.art-label{position:absolute;right:1%;bottom:11%;font:9px/1.7 var(--mono);letter-spacing:1px;color:rgba(135,226,229,.7);text-align:right}.pause-panel,.result-panel{position:absolute;left:10.5%;top:50%;transform:translateY(-50%);width:min(460px,80%)}.pause-panel h2,.result-panel h2{font-size:clamp(54px,7vw,86px)}.pause-panel p,.result-panel>p{color:#9ba9ae;font-size:16px}.quiet-button{background:none;border:0;color:#829398;font:11px var(--mono);letter-spacing:.8px;padding:14px 0;cursor:pointer}.quiet-button:hover{color:var(--cyan)}.pause-stats{display:flex;gap:16px;align-items:center;margin-top:25px;padding-top:14px;border-top:1px solid var(--line);font:10px var(--mono);color:#87969b}.pause-stats b{color:#edf3f3;margin-left:9px}.pause-stats i{font-style:normal;color:#52636a}.result-panel{width:min(500px,80%)}.result-panel h2{color:var(--cyan);font-size:clamp(62px,8vw,95px)}.result-score{display:flex;align-items:center;gap:20px;margin-top:25px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:18px 0}.result-score div{display:flex;flex-direction:column;gap:2px}.result-score small,.result-summary{font:9px var(--mono);color:#84949a;letter-spacing:.8px}.result-score strong{font:700 33px var(--display)}.result-score>span{color:#617179}.result-summary{display:flex;gap:22px;margin-top:13px}.result-summary b{color:#e1eeee;margin-left:8px}.result-panel .deploy-button{margin-top:24px}
/* live HUD */
#top-hud{position:absolute;top:4.5%;left:50%;transform:translateX(-50%);display:flex;align-items:center;justify-content:center;gap:28px;padding:9px 23px;background:linear-gradient(90deg,rgba(7,15,22,.92),rgba(7,15,22,.72),rgba(7,15,22,.92));border:1px solid rgba(185,230,232,.16);clip-path:polygon(0 0,100% 0,100% 78%,96% 100%,4% 100%,0 78%);min-width:370px}.team-score{display:flex;align-items:center;gap:9px;color:var(--blue)}.team-score.red{color:var(--red)}.team-score strong{font:600 24px var(--display);min-width:26px}.team-name{font:9px var(--mono);letter-spacing:.9px;color:#a8b7bb}.match-clock{display:flex;flex-direction:column;align-items:center;gap:1px;min-width:82px}.match-clock>span:nth-child(2){font:500 19px var(--mono);letter-spacing:1px}.match-clock small{font:7px var(--mono);letter-spacing:.7px;color:#788b91}.live-dot{position:absolute;top:14px;margin-left:-70px;width:5px;height:5px;border-radius:50%;background:var(--red);box-shadow:0 0 7px var(--red)}#objective{position:absolute;top:15.5%;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:8px;background:rgba(4,11,17,.55);padding:6px 12px;color:#bbc8ca;font:8px var(--mono);letter-spacing:.6px;white-space:nowrap}#objective i{font-style:normal;color:#5a7078}#objective b{font-weight:400;color:#82979d}.objective-icon{color:var(--cyan);font-size:13px}#minimap-frame{position:absolute;top:4.4%;left:3.3%;width:153px;padding:7px;background:rgba(6,15,21,.78);border:1px solid rgba(191,228,231,.19)}.map-label{display:block;color:#9db0b4;font:8px var(--mono);letter-spacing:.7px;margin:0 0 5px 2px}#minimap{width:100%;height:auto;display:block;opacity:.94}#killfeed{position:absolute;top:25%;right:3.5%;display:flex;flex-direction:column;gap:5px;align-items:flex-end}.feed-row{font:9px var(--mono);letter-spacing:.2px;background:rgba(5,13,18,.73);padding:6px 9px;border-right:2px solid var(--red);animation:feed-in .2s ease-out}.feed-row .killer{color:#91dfe2}.feed-row .victim{color:#ff8588}.feed-row .weapon{color:#a7b6ba;margin:0 7px}@keyframes feed-in{from{transform:translateX(15px);opacity:0}to{transform:none;opacity:1}}#crosshair{position:absolute;top:50%;left:50%;width:24px;height:24px;transform:translate(-50%,-50%);transition:transform .05s}#crosshair i{position:absolute;background:rgba(234,255,255,.9);box-shadow:0 0 3px rgba(35,235,234,.9)}#crosshair i:nth-child(1){width:2px;height:6px;left:11px;top:1px}#crosshair i:nth-child(2){width:2px;height:6px;left:11px;bottom:1px}#crosshair i:nth-child(3){width:6px;height:2px;left:1px;top:11px}#crosshair i:nth-child(4){width:6px;height:2px;right:1px;top:11px}#crosshair b{position:absolute;width:2px;height:2px;background:var(--cyan);left:11px;top:11px}#hit-marker{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);font:24px var(--mono);color:#ff666b;text-shadow:0 0 8px red}#center-status{position:absolute;top:23%;left:50%;transform:translateX(-50%);font:8px var(--mono);color:#9fb3b7;letter-spacing:1px;opacity:.72}#damage-vignette{position:absolute;inset:0;box-shadow:inset 0 0 80px 8px rgba(255,32,40,.75);opacity:0;pointer-events:none;transition:opacity .15s}#bottom-hud{position:absolute;left:0;right:0;bottom:0;height:100px;padding:14px 4.5% 13px;display:flex;align-items:flex-end;justify-content:space-between;background:linear-gradient(0deg,rgba(3,9,13,.91),rgba(4,10,14,.62) 72%,transparent)}.health-panel{display:grid;grid-template-columns:27px 48px 112px;align-items:center;gap:8px}.health-icon{width:25px;height:25px;display:grid;place-items:center;border:1px solid var(--cyan);color:var(--cyan);font:18px var(--mono);clip-path:polygon(0 0,100% 0,100% 78%,78% 100%,0 100%)}.health-panel>div:nth-child(2){display:flex;flex-direction:column}.health-panel small,.weapon-label small{font:8px var(--mono);color:#7f9298;letter-spacing:.8px}.health-panel strong{font:600 24px var(--display)}.health-track{grid-column:1/4;height:3px;background:#34444a;margin-top:2px}.health-track i{display:block;height:100%;background:var(--cyan);width:100%;transition:width .15s}.bottom-center{position:absolute;left:50%;bottom:18px;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:5px;color:#a4b2b6;font:8px var(--mono);letter-spacing:.65px;white-space:nowrap}.mode-tag{font-size:8px;color:#c1cdcf}.mode-tag span{display:inline-block;width:5px;height:5px;border-radius:50%;background:#7deab4;margin-right:5px;box-shadow:0 0 6px #7deab4}.bottom-center #tip{color:#72858b}.bottom-center #tip b{color:var(--cyan);font-weight:400;margin:0 4px}.ammo-panel{display:grid;grid-template-columns:1fr auto;align-items:end;column-gap:13px;min-width:142px}.weapon-label{display:flex;flex-direction:column;grid-column:1}.weapon-label strong{font:700 18px var(--display);letter-spacing:.4px}.weapon-label em{font-style:normal;font-size:10px;color:#8ea0a5;margin-left:4px}.ammo{grid-column:2;grid-row:1/3;display:flex;align-items:baseline;gap:4px}.ammo strong{font:500 34px var(--display);line-height:1;color:#f1f8f8}.ammo span{font:12px var(--mono);color:#87969a}.reload-line{grid-column:1/3;height:2px;background:#34444a;margin-top:5px}.reload-line i{display:block;width:0;height:100%;background:var(--cyan)}#controls-hint{position:absolute;bottom:115px;left:50%;transform:translateX(-50%);font:8px var(--mono);color:#91a2a7;letter-spacing:.5px;white-space:nowrap;text-shadow:0 1px 5px #000}kbd{font:8px var(--mono);color:#dae4e5;background:rgba(9,21,28,.8);border:1px solid rgba(216,242,242,.23);padding:3px 4px;margin:0 2px;border-radius:2px}#controls-hint span{color:var(--cyan);margin:0 3px}#toast{position:absolute;left:50%;top:33%;transform:translateX(-50%);font:10px var(--mono);letter-spacing:1px;color:#d4ffff;text-shadow:0 0 12px var(--cyan);opacity:0;transition:opacity .2s;white-space:nowrap}.toast-on{opacity:1!important}#mobile-controls{display:none}
@media(max-width:760px){#game-shell{width:100vw;height:100dvh;min-height:0}.screen{background:linear-gradient(90deg,rgba(4,11,17,.97),rgba(5,13,20,.77)),linear-gradient(0deg,rgba(4,11,17,.6),transparent 50%)}.menu-top{top:4%;left:6%;right:6%}.season{font-size:8px}.menu-content{left:8%;top:19%;width:84%}h1{font-size:clamp(61px,16vw,95px);margin-top:17px}.lead{font-size:15px;margin:14px 0 20px}.match-card,.deploy-button{width:min(100%,390px)}.hero-art{width:68%;height:57%;right:-18%;top:34%;opacity:.47}.hero-soldier{width:52%;right:25%}.menu-footer{left:6%;right:6%;bottom:3%;font-size:7px}.menu-footer span:last-child{font-size:7px}.pause-panel,.result-panel{left:8%;width:84%}#top-hud{top:3%;gap:12px;min-width:320px;padding:8px 14px}.team-score{gap:5px}.team-score strong{font-size:21px}.team-name{font-size:8px}.match-clock{min-width:66px}.match-clock>span:nth-child(2){font-size:17px}#minimap-frame{top:13%;left:3%;width:99px;padding:5px}.map-label{font-size:6px}#objective{top:9%;font-size:6px;gap:5px;padding:5px 7px}#objective b{display:none}#killfeed{top:27%;right:3%;max-width:65%}.feed-row{font-size:7px;padding:5px 7px}#bottom-hud{height:94px;padding:9px 4% 10px}.health-panel{grid-template-columns:22px 38px 62px;gap:5px}.health-icon{width:21px;height:21px;font-size:15px}.health-panel strong{font-size:20px}.health-panel small,.weapon-label small{font-size:7px}.ammo-panel{min-width:116px;column-gap:8px}.weapon-label strong{font-size:15px}.weapon-label em{font-size:8px}.ammo strong{font-size:29px}.ammo span{font-size:10px}.bottom-center{bottom:9px;font-size:6px}.mode-tag{font-size:6px}#tip{display:none}#controls-hint{display:none!important}#mobile-controls{display:block;position:absolute;inset:auto 0 94px;height:130px;pointer-events:none}.touch-pad{position:absolute;left:6%;bottom:5px;width:106px;height:106px;border:1px solid rgba(204,239,239,.34);border-radius:50%;background:rgba(5,13,19,.3);pointer-events:auto;touch-action:none}.touch-pad:before{content:'';position:absolute;inset:17px;border:1px dashed rgba(204,239,239,.2);border-radius:50%}.touch-pad i{position:absolute;width:39px;height:39px;border-radius:50%;left:33px;top:33px;background:rgba(87,227,229,.35);border:1px solid rgba(151,255,255,.65);box-shadow:0 0 12px rgba(73,226,229,.25)}.pad-label{position:absolute;top:-16px;left:50%;transform:translateX(-50%);font:7px var(--mono);color:#a9bec2;letter-spacing:1px}.touch-actions{pointer-events:auto;position:absolute;right:6%;bottom:7px;display:flex;align-items:flex-end;gap:13px}.touch-actions button{width:49px;height:49px;border:1px solid rgba(200,241,241,.38);border-radius:50%;background:rgba(5,13,19,.5);color:#d8f6f6;font:22px var(--display);touch-action:none}.touch-actions button small{display:block;font:6px var(--mono);color:#8ba1a5}.touch-actions #touch-fire{width:65px;height:65px;border-color:rgba(97,233,233,.75);background:rgba(48,180,185,.24);font-size:28px}.bottom-center{bottom:9px}#center-status{top:23%}}
@media(max-height:500px) and (min-width:761px){.menu-content{top:17%}h1{font-size:58px;margin:15px 0 10px}.lead{margin:10px 0 14px;font-size:14px}.match-card{padding:9px 12px}.brief-row{padding:8px 0}.deploy-button{height:43px;margin-top:10px}.hero-art{top:4%;height:92%}}

(() => {
'use strict';
const canvas=document.getElementById('view'),ctx=canvas.getContext('2d'),mini=document.getElementById('minimap'),mctx=mini.getContext('2d');
const $=id=>document.getElementById(id);
const ui={start:$('start-screen'),pause:$('pause-screen'),result:$('result-screen'),top:$('top-hud'),bottom:$('bottom-hud'),objective:$('objective'),map:$('minimap-frame'),cross:$('crosshair'),controls:$('controls-hint'),mobile:$('mobile-controls'),clock:$('clock'),blue:$('blue-score'),red:$('red-score'),health:$('health'),healthbar:$('health-bar'),ammo:$('ammo'),feed:$('killfeed'),hit:$('hit-marker'),damage:$('damage-vignette'),toast:$('toast')};
const MAP=[
'####################','#....#.......#.....#','#....#.......#.....#','#........#.........#','###.##...#...##.####','#...#.........#....#','#...#..##.##...#....#','#..................#','#..##..#....#..##...#','#......#....#.......#','#......#....#.......#','#..##..#....#..##...#','#..................#','#...#..##.##...#....#','#...#.........#....#','####.##...#...##.####','#........#.........#','#....#.......#.....#','#....#.......#.....#','####################'];
const W=20,H=20,FOV=Math.PI*.39,PI2=Math.PI*2;
const colorBlue='#51dce5',colorRed='#ff636b';
let game={active:false,paused:false,over:false,time:600,blue:0,red:0,kills:0,shots:0,hits:0,health:100,ammo:30,reserve:120,reload:0,respawn:0,damage:0,hitTime:0,fireWait:0,shake:0,last:0,toastTime:0};
let player={x:2.5,y:2.5,angle:0,pitch:0},keys={},bots=[],zBuffer=[],viewW=960,viewH=540,rayCount=480,mouseLook=false,touchLook=null,moveTouch={x:0,y:0},fireHeld=false;
const starts={blue:[{x:2.5,y:2.5},{x:3.5,y:2.5},{x:2.5,y:3.5},{x:4.5,y:2.5}],red:[{x:17.5,y:17.5},{x:16.5,y:17.5},{x:17.5,y:16.5},{x:15.5,y:17.5}]};
const isWall=(x,y)=>{const a=Math.floor(x),b=Math.floor(y);return a<0||b<0||a>=W||b>=H||MAP[b][a]==='#'};
const norm=a=>{while(a>Math.PI)a-=PI2;while(a< -Math.PI)a+=PI2;return a};
function resize(){const r=canvas.getBoundingClientRect();const d=Math.min(devicePixelRatio||1,1.35);canvas.width=Math.max(480,Math.floor(r.width*d));canvas.height=Math.max(270,Math.floor(r.height*d));viewW=canvas.width;viewH=canvas.height;rayCount=Math.max(320,Math.floor(viewW*.5));ctx.imageSmoothingEnabled=false}
window.addEventListener('resize',resize);resize();
function createBots(){bots=[];for(const team of ['blue','red'])for(let i=0;i<4;i++){const p=starts[team][i];if(team==='blue'&&i===0)continue;bots.push({team,name:(team==='blue'?['','KITE','ROOK','ECHO'][i]:['VEX','MERC','NOVA','ZERO'][i]),x:p.x,y:p.y,angle:team==='blue'?0:Math.PI,hp:100,alive:true,respawn:0,cooldown:Math.random()*1.5,strafe:Math.random()<.5?-1:1,think:0,tx:p.x,ty:p.y,flash:0})}}
function setLiveUI(on){['top','bottom','objective','map','cross','controls','mobile'].forEach(k=>ui[k].classList.toggle('hidden',!on));}
function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('toast-on');game.toastTime=1.5}
function startGame(){game={active:true,paused:false,over:false,time:600,blue:0,red:0,kills:0,shots:0,hits:0,health:100,ammo:30,reserve:120,reload:0,respawn:0,damage:0,hitTime:0,fireWait:0,shake:0,last:performance.now(),toastTime:0};player={x:2.5,y:2.5,angle:0,pitch:0};keys={};createBots();ui.start.classList.add('hidden');ui.pause.classList.add('hidden');ui.result.classList.add('hidden');setLiveUI(true);if(innerWidth>760&&canvas.requestPointerLock)canvas.requestPointerLock();showToast('PHANTOM SQUAD — MOVE OUT');updateHUD()}
function finishGame(){game.active=false;game.over=true;setLiveUI(false);if(document.pointerLockElement)document.exitPointerLock();ui.result.classList.remove('hidden');const won=game.blue>game.red; $('result-title').textContent=game.blue===game.red?'DRAW':won?'VICTORY':'DEFEAT';$('result-title').style.color=game.blue===game.red?'#edf3f3':won?'#61e9e9':'#ff646b';$('result-copy').textContent=game.blue===game.red?'BOTH SQUADS FIGHT TO A STANDSTILL.':won?'PHANTOM SQUAD OWNS THE FRONTLINE.':'VANGUARD HOLDS THE FRONTLINE.';$('result-blue').textContent=String(game.blue).padStart(2,'0');$('result-red').textContent=String(game.red).padStart(2,'0');$('result-kills').textContent=String(game.kills).padStart(2,'0');$('result-accuracy').textContent=(game.shots?Math.round(game.hits/game.shots*100):0)+'%'}
function pauseGame(){if(!game.active||game.over)return;game.paused=!game.paused;ui.pause.classList.toggle('hidden',!game.paused);if(game.paused){if(document.pointerLockElement)document.exitPointerLock();$('pause-blue').textContent=String(game.blue).padStart(2,'0');$('pause-red').textContent=String(game.red).padStart(2,'0')}else{game.last=performance.now();if(innerWidth>760&&canvas.requestPointerLock)canvas.requestPointerLock()}}
function reload(){if(!game.active||game.paused||game.reload>0||game.ammo>=30||game.reserve<=0)return;game.reload=1.35;showToast('RELOADING')}
function updateHUD(){ui.blue.textContent=String(game.blue).padStart(2,'0');ui.red.textContent=String(game.red).padStart(2,'0');ui.health.textContent=Math.max(0,Math.ceil(game.health));ui.healthbar.style.width=Math.max(0,game.health)+'%';ui.healthbar.style.background=game.health<30?'#ff646b':'#61e9e9';ui.ammo.textContent=game.reload>0?'··':game.ammo;const sec=Math.ceil(game.time);ui.clock.textContent=`${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`;$('reload-bar').style.width=game.reload>0?`${(1.35-game.reload)/1.35*100}%`:'0%'}
$('deploy').addEventListener('click',startGame);$('resume').addEventListener('click',pauseGame);$('quit').addEventListener('click',()=>{game.active=false;game.paused=false;setLiveUI(false);ui.pause.classList.add('hidden');ui.start.classList.remove('hidden');if(document.pointerLockElement)document.exitPointerLock()});$('again').addEventListener('click',startGame);
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Escape'&&game.active)pauseGame();if(e.code==='KeyR')reload()});window.addEventListener('keyup',e=>keys[e.code]=false);
document.addEventListener('pointerlockchange',()=>{mouseLook=document.pointerLockElement===canvas});canvas.addEventListener('click',()=>{if(game.active&&!game.paused&&innerWidth>760&&!mouseLook)canvas.requestPointerLock?.()});document.addEventListener('mousemove',e=>{if(mouseLook&&game.active&&!game.paused){player.angle=norm(player.angle+e.movementX*.0022);player.pitch=Math.max(-90,Math.min(90,player.pitch+e.movementY*.23))}});
