function bindHold(id,fn){const el=$(id);el.addEventListener('pointerdown',e=>{e.preventDefault();fn(true);el.setPointerCapture?.(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>el.addEventListener(ev,e=>{e.preventDefault();fn(false)}))}bindHold('touch-fire',v=>fireHeld=v);$('touch-reload').addEventListener('pointerdown',e=>{e.preventDefault();reload()});
