function tryMove(ent,dx,dy){const rad=ent===player?.19:.2;const nx=ent.x+dx,ny=ent.y+dy;if(!isWall(nx+Math.sign(dx)*rad,ent.y+Math.sign(dy)*rad)&&!isWall(nx+Math.sign(dx)*rad,ent.y)&&!isWall(ent.x,ny+Math.sign(dy)*rad)){ent.x=nx;ent.y=ny}else{if(!isWall(nx+Math.sign(dx)*rad,ent.y))ent.x=nx;if(!isWall(ent.x,ny+Math.sign(dy)*rad))ent.y=ny}}
