function zAtAngle(){return 100}
function shoot(){if(!game.active||game.paused||game.respawn>0)return;if(game.reload>0)return;if(game.ammo<=0){reload();return}if(game.fireWait>0)return;game.fireWait=.105;game.ammo--;game.shake=.09;hitEnemy();updateHUD()}
