function addFeed(killer,victim,team){const row=document.createElement('div');row.className='feed-row';row.style.borderColor=team==='red'?'var(--red)':'var(--blue)';row.innerHTML=`<span class="killer">${killer}</span><span class="weapon">╳</span><span class="victim">${victim}</span>`;ui.feed.prepend(row);while(ui.feed.children.length>4)ui.feed.lastChild.remove();setTimeout(()=>row.remove(),4200)}
