function respawnPlayer(){const p=starts.blue[0];player.x=p.x;player.y=p.y;player.angle=0;game.health=100;game.ammo=30;game.reserve=Math.max(0,game.reserve-15);game.respawn=0;showToast('BACK IN THE FIGHT')}
function pickTarget(bot){let target=null,dist=Infinity;if(bot.team==='red'&&game.respawn<=0){const d=Math.hypot(player.x-bot.x,player.y-bot.y);if(d<dist){dist=d;target=player}}for(const other of bots){if(!other.alive||other===bot||other.team===bot.team)continue;const d=Math.hypot(other.x-bot.x,other.y-bot.y);if(d<dist){dist=d;target=other}}return target?{target,dist}:null}
function updateBots(dt){for(const b of bots){if(!b.alive){b.respawn-=dt;if(b.respawn<=0)respawnBot(b);continue}b.cooldown-=dt;b.think-=dt;const found=pickTarget(b);if(found){const t=found.target,dx=t.x-b.x,dy=t.y-b.y,ang=Math.atan2(dy,dx),visible=found.dist<11&&hasLOS(b.x,b.y,t.x,t.y);b.angle=norm(b.angle+Math.max(-2.8*dt,Math.min(2.8*dt,norm(ang-b.angle))));if(visible){if(found.dist>2.8)tryMove(b,Math.cos(b.angle)*dt*.95,Math.sin(b.angle)*dt*.95);else{tryMove(b,Math.cos(b.angle+Math.PI/2*b.strafe)*dt*.55,Math.sin(b.angle+Math.PI/2*b.strafe)*dt*.55);if(Math.random()<dt*.22)b.strafe*=-1}if(b.cooldown<=0){b.cooldown=.72+Math.random()*.75;if(Math.random()<Math.max(.16,.66-found.dist*.035)){if(t===player)damagePlayer(8+Math.random()*8,b.name);else{t.hp-=22;if(t.hp<=0)killBot(t,b.name)}}}}else{if(b.think<=0){b.think=1.5+Math.random()*2;const a=Math.random()*PI2;b.tx=Math.max(1.5,Math.min(18.5,b.x+Math.cos(a)*(2+Math.random()*4)));b.ty=Math.max(1.5,Math.min(18.5,b.y+Math.sin(a)*(2+Math.random()*4)))}const a=Math.atan2(b.ty-b.y,b.tx-b.x);tryMove(b,Math.cos(a)*dt*.65,Math.sin(a)*dt*.65)}}else if(b.think<=0){b.think=2;b.tx=b.team==='blue'?4+Math.random()*3:13+Math.random()*3;b.ty=4+Math.random()*12}if(!found){const a=Math.atan2(b.ty-b.y,b.tx-b.x);b.angle=norm(b.angle+Math.max(-1.3*dt,Math.min(1.3*dt,norm(a-b.angle))));tryMove(b,Math.cos(b.angle)*dt*.45,Math.sin(b.angle)*dt*.45)}}}}
function update(dt){if(!game.active||game.paused)return;game.time-=dt;if(game.time<=0){game.time=0;finishGame();return}if(game.respawn>0){game.respawn-=dt;if(game.respawn<=0)respawnPlayer()}else{let f=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)+(-moveTouch.y),s=(keys.KeyD?1:0)-(keys.KeyA?1:0)+moveTouch.x;const speed=(keys.ShiftLeft||keys.ShiftRight?3.9:2.65)*dt,l=Math.hypot(f,s)||1;f/=l;s/=l;const dx=(Math.cos(player.angle)*f-Math.sin(player.angle)*s)*speed,dy=(Math.sin(player.angle)*f+Math.cos(player.angle)*s)*speed;tryMove(player,dx,dy)}if(game.fireWait>0)game.fireWait-=dt;if(game.shake>0)game.shake-=dt;if(game.damage>0){game.damage=Math.max(0,game.damage-dt*2.7);ui.damage.style.opacity=String(game.damage*.78)}if(game.hitTime>0){game.hitTime-=dt;if(game.hitTime<=0)ui.hit.classList.add('hidden')}if(game.toastTime>0){game.toastTime-=dt;if(game.toastTime<=0)ui.toast.classList.remove('toast-on')}if(game.reload>0){game.reload-=dt;if(game.reload<=0){const n=Math.min(30-game.ammo,game.reserve);game.ammo+=n;game.reserve-=n;updateHUD()}}updateBots(dt);if(fireHeld)shoot();updateHUD()}
function raycast(angle){const dx=Math.cos(angle),dy=Math.sin(angle);let mapX=Math.floor(player.x),mapY=Math.floor(player.y),deltaX=Math.abs(1/dx),deltaY=Math.abs(1/dy),stepX,stepY,sideX,sideY;if(dx<0){stepX=-1;sideX=(player.x-mapX)*deltaX}else{stepX=1;sideX=(mapX+1-player.x)*deltaX}if(dy<0){stepY=-1;sideY=(player.y-mapY)*deltaY}else{stepY=1;sideY=(mapY+1-player.y)*deltaY}let side=0,steps=0;while(steps++<48){if(sideX<sideY){sideX+=deltaX;mapX+=stepX;side=0}else{sideY+=deltaY;mapY+=stepY;side=1}if(mapX<0||mapY<0||mapX>=W||mapY>=H||MAP[mapY][mapX]==='#')break}let d=side===0?sideX-deltaX:sideY-deltaY;d=Math.max(.08,d);const wallX=side===0?player.y+d*dy:player.x+d*dx;return{d,side,wallX:wallX-Math.floor(wallX),mapX,mapY}}
function render(){const w=viewW,h=viewH;if(!w||!h)return;const horizon=h*.5+player.pitch*h*.002;const sky=ctx.createLinearGradient(0,0,0,horizon);sky.addColorStop(0,'#101d27');sky.addColorStop(.7,'#1b303a');sky.addColorStop(1,'#34434a');ctx.fillStyle=sky;ctx.fillRect(0,0,w,horizon);const glow=ctx.createRadialGradient(w*.52,horizon*.93,2,w*.52,horizon,Math.min(w,h)*.5);glow.addColorStop(0,'rgba(85,163,169,.19)');glow.addColorStop(1,'rgba(40,70,78,0)');ctx.fillStyle=glow;ctx.fillRect(0,0,w,horizon+18);const floor=ctx.createLinearGradient(0,horizon,0,h);floor.addColorStop(0,'#3b4548');floor.addColorStop(.18,'#252e32');floor.addColorStop(1,'#10191e');ctx.fillStyle=floor;ctx.fillRect(0,horizon,w,h-horizon);
// perspective floor seams
