renderActors(horizon);renderWeapon(w,h);if(game.active){drawMinimap();if(game.respawn>0){ctx.fillStyle=`rgba(2,7,10,${Math.min(.72,.48+Math.sin(performance.now()*.006)*.08)})`;ctx.fillRect(0,0,w,h);ctx.fillStyle='#ff777a';ctx.font=`${Math.round(h*.03)}px "DM Mono", monospace`;ctx.textAlign='center';ctx.fillText('RESPAWNING',w/2,h*.45);ctx.fillStyle='#d5e5e5';ctx.font=`${Math.round(h*.018)}px "DM Mono", monospace`;ctx.fillText(`${Math.ceil(game.respawn)} SEC`,w/2,h*.49)}}}

