function updateBots(dt){
  for(const b of bots){
    if(!b.alive){b.respawn-=dt;if(b.respawn<=0)respawnBot(b);continue}
    b.cooldown-=dt;b.think-=dt;const found=pickTarget(b);
    if(found){
      const t=found.target,dx=t.x-b.x,dy=t.y-b.y,ang=Math.atan2(dy,dx),visible=found.dist<11&&hasLOS(b.x,b.y,t.x,t.y);
      b.angle=norm(b.angle+Math.max(-2.8*dt,Math.min(2.8*dt,norm(ang-b.angle))));
      if(visible){
        if(found.dist>2.8)tryMove(b,Math.cos(b.angle)*dt*.95,Math.sin(b.angle)*dt*.95);
        else{tryMove(b,Math.cos(b.angle+Math.PI/2*b.strafe)*dt*.55,Math.sin(b.angle+Math.PI/2*b.strafe)*dt*.55);if(Math.random()<dt*.22)b.strafe*=-1}
        if(b.cooldown<=0){b.cooldown=.72+Math.random()*.75;if(Math.random()<Math.max(.16,.66-found.dist*.035)){if(t===player)damagePlayer(8+Math.random()*8,b.name);else{t.hp-=22;if(t.hp<=0)killBot(t,b.name)}}}
      }else if(b.think<=0){b.think=1.5+Math.random()*2;const a=Math.random()*PI2;b.tx=Math.max(1.5,Math.min(18.5,b.x+Math.cos(a)*(2+Math.random()*4)));b.ty=Math.max(1.5,Math.min(18.5,b.y+Math.sin(a)*(2+Math.random()*4)))}
    }else if(b.think<=0){b.think=2;b.tx=b.team==='blue'?4+Math.random()*3:13+Math.random()*3;b.ty=4+Math.random()*12}
    if(!found){const a=Math.atan2(b.ty-b.y,b.tx-b.x);b.angle=norm(b.angle+Math.max(-1.3*dt,Math.min(1.3*dt,norm(a-b.angle))));tryMove(b,Math.cos(b.angle)*dt*.45,Math.sin(b.angle)*dt*.45)}
  }
}

